package models

// Expression represents a Go type expression.
type Expression struct {
	Value       string // rendered type string, e.g. "*Foo", "[]int"
	IsStar      bool   // pointer type
	IsVariadic  bool
	Underlying  string // for defined types, the underlying type identifier
}

// String returns the type string to write in source code.
func (e *Expression) String() string {
	if e.IsVariadic {
		return "[]" + e.Value
	}
	return e.Value
}

// Field represents a named (or anonymous) typed value, such as a parameter,
// named result, or a struct field.
type Field struct {
	Name       string
	Type       *Expression
	Index      int
	IsNamed    bool // for results, whether the return value was named
}

// Receiver represents the receiver of a method.
type Receiver struct {
	Field
	Fields []*Field // struct fields (if receiver's type is a struct)
	IsStruct bool
	TypeName string // "T" or "Box[T]" for display/call
	ConcreteTypeName string // "T" or "Box[int]" instantiated
}

// TypeParam is a generic type parameter.
type TypeParam struct {
	Name       string
	Constraint string
	Concrete   string // default instantiation for tests
}

// Function represents a parsed Go function/method.
type Function struct {
	Name         string // "Add" or "Method"
	IsExported   bool
	Receiver     *Receiver
	TypeParams   []*TypeParam
	Parameters   []*Field
	Results      []*Field
	ReturnsError bool
	ReturnsOnlyError bool
}

// TestName returns the proper test function name (e.g. "TestAdd", "TestT_Method").
func (f *Function) TestName() string {
	if f.Receiver != nil {
		tn := f.Receiver.TypeName
		// strip type params like [T] from TestName
		if i := indexAny(tn, '['); i >= 0 {
			tn = tn[:i]
		}
		if isExported(tn) {
			return "Test" + tn + "_" + f.Name
		}
		return "Test_" + tn + "_" + f.Name
	}
	if f.IsExported {
		return "Test" + f.Name
	}
	return "Test_" + f.Name
}

// DisplayName returns the name used in error messages like "T.Method".
func (f *Function) DisplayName() string {
	if f.Receiver != nil {
		return f.Receiver.TypeName + "." + f.Name
	}
	return f.Name
}

func isExported(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	return c >= 'A' && c <= 'Z'
}

func indexAny(s string, c byte) int {
	for i := 0; i < len(s); i++ {
		if s[i] == c {
			return i
		}
	}
	return -1
}
EOF
