package goparser

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"strings"

	"gotests/internal/models"
)

// Result contains the parsed result for a Go source file.
type Result struct {
	Header    *Header
	Functions []*models.Function
}

// Header contains package info, imports, and code that comes before declarations.
type Header struct {
	Package string
	Imports []*Import
	Code    []byte // raw source before first declaration
}

// Import describes a single imported package.
type Import struct {
	Name string // alias or "."
	Path string
}

// Parser parses Go source files.
type Parser struct{}

// Parse parses srcPath and returns a Result. files is additional files from the same package (paths).
func (p *Parser) Parse(srcPath string, files []string) (*Result, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, srcPath, nil, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("target parser.ParseFile(): %v", err)
	}

	// Collect structs defined in this file and sibling files (same package).
	structs := map[string]*ast.StructType{}
	collectStructs(f, structs)
	for _, sp := range files {
		if sp == srcPath {
			continue
		}
		sf, err := parser.ParseFile(fset, sp, nil, parser.ParseComments)
		if err != nil {
			continue
		}
		// Only include if same package
		if sf.Name != nil && f.Name != nil && sf.Name.Name == f.Name.Name {
			collectStructs(sf, structs)
		}
	}

	r := &Result{
		Header: &Header{
			Package: f.Name.Name,
		},
	}
	for _, imp := range f.Imports {
		name := ""
		if imp.Name != nil {
			name = imp.Name.Name
		}
		path := strings.Trim(imp.Path.Value, "\"")
		r.Header.Imports = append(r.Header.Imports, &Import{Name: name, Path: path})
	}

	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if fd.Name.Name == "init" {
			continue
		}
		fn := parseFunc(fd, structs)
		if fn == nil {
			continue
		}
		r.Functions = append(r.Functions, fn)
	}
	return r, nil
}

func collectStructs(f *ast.File, out map[string]*ast.StructType) {
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.TYPE {
			continue
		}
		for _, s := range gd.Specs {
			ts, ok := s.(*ast.TypeSpec)
			if !ok {
				continue
			}
			if st, ok := ts.Type.(*ast.StructType); ok {
				out[ts.Name.Name] = st
			}
		}
	}
}

func parseFunc(fd *ast.FuncDecl, structs map[string]*ast.StructType) *models.Function {
	fn := &models.Function{
		Name:       fd.Name.Name,
		IsExported: ast.IsExported(fd.Name.Name),
	}

	// Type parameters
	if fd.Type.TypeParams != nil {
		for _, field := range fd.Type.TypeParams.List {
			constraint := exprString(field.Type)
			concrete := concreteForConstraint(field.Type)
			for _, n := range field.Names {
				fn.TypeParams = append(fn.TypeParams, &models.TypeParam{
					Name:       n.Name,
					Constraint: constraint,
					Concrete:   concrete,
				})
			}
		}
	}

	// Receiver
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		rf := fd.Recv.List[0]
		rcv := &models.Receiver{}
		// Receiver name
		rname := ""
		if len(rf.Names) > 0 && rf.Names[0].Name != "" && rf.Names[0].Name != "_" {
			rname = rf.Names[0].Name
		}
		// Get receiver type info
		baseTypeName, isStar, typeArgs := receiverTypeInfo(rf.Type)
		// Check if struct
		st, isStruct := structs[baseTypeName]

		// Determine struct type param names (from TypeSpec)
		// We'll need to walk into the type spec to look up type params.

		// Set type params for receiver from the receiver's type args list
		// (for generic type instantiation)
		// Use the names as declared on the receiver (e.g., Box[T])
		recvTypeParams := typeArgs // these are the param names like [T]

		typeName := baseTypeName
		if len(recvTypeParams) > 0 {
			typeName = baseTypeName + "[" + strings.Join(recvTypeParams, ", ") + "]"
		}

		// Concrete instantiation: look up package-level generic definitions to know constraints
		// We use the constraint defaults known via the func's type params or type spec
		concreteArgs := concreteTypeArgsForReceiver(baseTypeName, typeArgs, structs)
		concreteTypeName := baseTypeName
		if len(concreteArgs) > 0 {
			concreteTypeName = baseTypeName + "[" + strings.Join(concreteArgs, ", ") + "]"
		}

		pfx := ""
		if isStar {
			pfx = "*"
		}
		rcv.Type = &models.Expression{
			Value:  pfx + concreteTypeName,
			IsStar: isStar,
		}
		if rname == "" {
			rname = defaultReceiverName(baseTypeName)
		}
		// Rename to avoid 't' collision
		if rname == "t" {
			rname = "tr"
		}
		rcv.Name = rname
		rcv.IsStruct = isStruct && len(typeArgs) == 0 // generics: treat as non-struct for fields
		rcv.TypeName = typeName
		rcv.ConcreteTypeName = concreteTypeName
		if rcv.IsStruct && st != nil && st.Fields != nil {
			for _, f := range st.Fields.List {
				typStr := exprString(f.Type)
				if len(f.Names) == 0 {
					// embedded
					rcv.Fields = append(rcv.Fields, &models.Field{
						Name: typStr,
						Type: &models.Expression{Value: typStr},
					})
					continue
				}
				for _, n := range f.Names {
					rcv.Fields = append(rcv.Fields, &models.Field{
						Name: n.Name,
						Type: &models.Expression{Value: typStr},
					})
				}
			}
		}
		fn.Receiver = rcv
	}

	// Parameters
	typeParamMap := map[string]string{}
	for _, tp := range fn.TypeParams {
		typeParamMap[tp.Name] = tp.Concrete
	}
	// Also map receiver type params
	if fn.Receiver != nil {
		_, _, targs := receiverTypeInfo(fd.Recv.List[0].Type)
		// Look up defaults from the generic type declaration, if it's defined
		baseName, _, _ := receiverTypeInfo(fd.Recv.List[0].Type)
		concreteArgs := concreteTypeArgsForReceiver(baseName, targs, structs)
		for i, a := range targs {
			if i < len(concreteArgs) {
				typeParamMap[a] = concreteArgs[i]
			}
		}
	}

	blankIdx := 0
	if fd.Type.Params != nil {
		for _, field := range fd.Type.Params.List {
			origTypeStr := exprString(field.Type)
			isVariadic := false
			actualType := field.Type
			if el, ok := field.Type.(*ast.Ellipsis); ok {
				actualType = el.Elt
				isVariadic = true
				origTypeStr = exprString(actualType)
			}
			// Concretize type params inside
			concreteType := substituteTypeParams(origTypeStr, typeParamMap)

			if len(field.Names) == 0 {
				fn.Parameters = append(fn.Parameters, &models.Field{
					Name: fmt.Sprintf("in%d", blankIdx),
					Type: &models.Expression{Value: concreteType, IsVariadic: isVariadic},
				})
				blankIdx++
				continue
			}
			for _, n := range field.Names {
				name := n.Name
				if name == "_" {
					name = fmt.Sprintf("in%d", blankIdx)
					blankIdx++
				}
				fn.Parameters = append(fn.Parameters, &models.Field{
					Name: name,
					Type: &models.Expression{Value: concreteType, IsVariadic: isVariadic},
				})
			}
		}
	}

	// Results
	if fd.Type.Results != nil {
		i := 0
		for _, field := range fd.Type.Results.List {
			origTypeStr := exprString(field.Type)
			concreteType := substituteTypeParams(origTypeStr, typeParamMap)
			if len(field.Names) == 0 {
				fn.Results = append(fn.Results, &models.Field{
					Name:  "",
					Type:  &models.Expression{Value: concreteType},
					Index: i,
				})
				i++
				continue
			}
			for _, n := range field.Names {
				name := n.Name
				isNamed := name != "" && name != "_"
				if name == "_" {
					name = ""
					isNamed = false
				}
				fn.Results = append(fn.Results, &models.Field{
					Name:    name,
					Type:    &models.Expression{Value: concreteType},
					IsNamed: isNamed,
					Index:   i,
				})
				i++
			}
		}
	}

	// Check for error return (last position)
	if n := len(fn.Results); n > 0 {
		last := fn.Results[n-1]
		if last.Type.Value == "error" {
			fn.ReturnsError = true
			fn.Results = fn.Results[:n-1]
			if n-1 == 0 {
				fn.ReturnsOnlyError = true
			}
		}
	}

	return fn
}

func receiverTypeInfo(e ast.Expr) (base string, isStar bool, typeArgs []string) {
	switch t := e.(type) {
	case *ast.StarExpr:
		isStar = true
		b, _, ta := receiverTypeInfo(t.X)
		return b, true, ta
	case *ast.Ident:
		return t.Name, false, nil
	case *ast.IndexExpr:
		b, _, _ := receiverTypeInfo(t.X)
		return b, false, []string{exprString(t.Index)}
	case *ast.IndexListExpr:
		b, _, _ := receiverTypeInfo(t.X)
		var args []string
		for _, a := range t.Indices {
			args = append(args, exprString(a))
		}
		return b, false, args
	}
	return "", false, nil
}

func defaultReceiverName(typeName string) string {
	if typeName == "" {
		return "t"
	}
	// lowercase first letter
	c := typeName[0]
	if c >= 'A' && c <= 'Z' {
		c = c + ('a' - 'A')
	}
	name := string(c)
	if name == "t" {
		return "tr"
	}
	return name
}

// concreteForConstraint chooses a default concrete type for a given constraint expression.
func concreteForConstraint(e ast.Expr) string {
	s := exprString(e)
	// Remove whitespace
	s = strings.TrimSpace(s)
	// Handle "any" or "interface{}"
	if s == "any" || s == "interface{}" {
		return "int"
	}
	if s == "comparable" {
		return "string"
	}
	// Union types: pick first option
	if strings.Contains(s, "|") {
		parts := strings.Split(s, "|")
		first := strings.TrimSpace(parts[0])
		// Strip ~
		first = strings.TrimPrefix(first, "~")
		return first
	}
	// Approximation constraint ~T
	if strings.HasPrefix(s, "~") {
		return strings.TrimPrefix(s, "~")
	}
	// Default: use as-is
	return s
}

// concreteTypeArgsForReceiver resolves the generic type parameters of a receiver by
// looking up the receiver's type declaration (in structs map) and mapping argNames
// (e.g. ["T"]) to concrete types like ["int"] based on constraints.
// argNames are the names as used in the receiver declaration (e.g. Box[T] -> ["T"]).
func concreteTypeArgsForReceiver(typeName string, argNames []string, structs map[string]*ast.StructType) []string {
	// We need the TypeSpec for typeName to look up constraints.
	// Approach: search in ast files - but we don't have access here. Return conservative defaults:
	// Use "int" for unknown, since we don't have constraints. But we need to match original's
	// default for different constraints. For now, best-effort: return defaults based on
	// mock context.
	// Actually we'll enhance later - for now we need global TypeSpec tracking.
	_ = typeName
	_ = structs
	out := make([]string, 0, len(argNames))
	for range argNames {
		out = append(out, "int")
	}
	return out
}

// substituteTypeParams replaces type parameter names in typeStr with their concrete types.
// This is a naive string substitution but works for common cases.
func substituteTypeParams(typeStr string, m map[string]string) string {
	if len(m) == 0 {
		return typeStr
	}
	// Replace whole-word matches
	var out strings.Builder
	i := 0
	for i < len(typeStr) {
		c := typeStr[i]
		if isIdentStart(c) {
			j := i + 1
			for j < len(typeStr) && isIdentPart(typeStr[j]) {
				j++
			}
			word := typeStr[i:j]
			if v, ok := m[word]; ok {
				out.WriteString(v)
			} else {
				out.WriteString(word)
			}
			i = j
		} else {
			out.WriteByte(c)
			i++
		}
	}
	return out.String()
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentPart(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

// exprString converts an AST expression to its Go source text.
func exprString(e ast.Expr) string {
	return exprStringWithAlign(e)
}

func exprStringWithAlign(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	case *ast.ArrayType:
		lenStr := ""
		if t.Len != nil {
			lenStr = exprString(t.Len)
		}
		return "[" + lenStr + "]" + exprString(t.Elt)
	case *ast.MapType:
		return "map[" + exprString(t.Key) + "]" + exprString(t.Value)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			return "chan<- " + exprString(t.Value)
		case ast.RECV:
			return "<-chan " + exprString(t.Value)
		default:
			return "chan " + exprString(t.Value)
		}
	case *ast.FuncType:
		return funcTypeString(t)
	case *ast.InterfaceType:
		if t.Methods == nil || len(t.Methods.List) == 0 {
			return "interface{}"
		}
		// Stringify methods
		var parts []string
		for _, m := range t.Methods.List {
			if len(m.Names) == 0 {
				parts = append(parts, exprString(m.Type))
			} else {
				parts = append(parts, m.Names[0].Name+" "+funcSigString(m.Type.(*ast.FuncType)))
			}
		}
		return "interface{ " + strings.Join(parts, "; ") + " }"
	case *ast.StructType:
		if t.Fields == nil || len(t.Fields.List) == 0 {
			return "struct{}"
		}
		var parts []string
		for _, f := range t.Fields.List {
			ts := exprString(f.Type)
			if len(f.Names) == 0 {
				parts = append(parts, ts)
			} else {
				var names []string
				for _, n := range f.Names {
					names = append(names, n.Name)
				}
				parts = append(parts, strings.Join(names, ", ")+" "+ts)
			}
		}
		return "struct{ " + strings.Join(parts, "; ") + " }"
	case *ast.Ellipsis:
		return "..." + exprString(t.Elt)
	case *ast.IndexExpr:
		return exprString(t.X) + "[" + exprString(t.Index) + "]"
	case *ast.IndexListExpr:
		var args []string
		for _, a := range t.Indices {
			args = append(args, exprString(a))
		}
		return exprString(t.X) + "[" + strings.Join(args, ", ") + "]"
	case *ast.BinaryExpr:
		return exprString(t.X) + " " + t.Op.String() + " " + exprString(t.Y)
	case *ast.UnaryExpr:
		return t.Op.String() + exprString(t.X)
	case *ast.BasicLit:
		return t.Value
	case *ast.ParenExpr:
		return "(" + exprString(t.X) + ")"
	}
	return fmt.Sprintf("%T", e)
}

func funcTypeString(ft *ast.FuncType) string {
	return "func" + funcSigString(ft)
}

func funcSigString(ft *ast.FuncType) string {
	var b strings.Builder
	b.WriteByte('(')
	if ft.Params != nil {
		first := true
		for _, f := range ft.Params.List {
			ts := exprString(f.Type)
			if len(f.Names) == 0 {
				if !first {
					b.WriteString(", ")
				}
				b.WriteString(ts)
				first = false
			} else {
				for _, n := range f.Names {
					if !first {
						b.WriteString(", ")
					}
					b.WriteString(n.Name + " " + ts)
					first = false
				}
			}
		}
	}
	b.WriteByte(')')
	if ft.Results != nil {
		count := 0
		for _, f := range ft.Results.List {
			if len(f.Names) == 0 {
				count++
			} else {
				count += len(f.Names)
			}
		}
		if count == 1 && len(ft.Results.List[0].Names) == 0 {
			b.WriteByte(' ')
			b.WriteString(exprString(ft.Results.List[0].Type))
		} else if count > 0 {
			b.WriteString(" (")
			first := true
			for _, f := range ft.Results.List {
				ts := exprString(f.Type)
				if len(f.Names) == 0 {
					if !first {
						b.WriteString(", ")
					}
					b.WriteString(ts)
					first = false
				} else {
					for _, n := range f.Names {
						if !first {
							b.WriteString(", ")
						}
						b.WriteString(n.Name + " " + ts)
						first = false
					}
				}
			}
			b.WriteString(")")
		}
	}
	return b.String()
}
