package goparser

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"strings"

	"gotests/internal/models"
)

// Result contains the parsed result for a Go source file.
type Result struct {
	Header    *Header
	Functions []*models.Function
}

// Header contains package info, imports, and code that comes before declarations.
type Header struct {
	Package string
	Imports []*Import
	Code    []byte
}

// Import describes a single imported package.
type Import struct {
	Name string
	Path string
}

// typeInfo holds information about a type declaration.
type typeInfo struct {
	Name       string
	TypeParams []*models.TypeParam
	Struct     *ast.StructType // nil if not a struct
}

// Parser parses Go source files.
type Parser struct{}

// Parse parses srcPath and returns a Result.
func (p *Parser) Parse(srcPath string, files []string) (*Result, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, srcPath, nil, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("target parser.ParseFile(): %v", err)
	}

	// Collect type declarations across sibling files.
	types := map[string]*typeInfo{}
	collectTypes(f, types)
	for _, sp := range files {
		if sp == srcPath {
			continue
		}
		sf, err := parser.ParseFile(fset, sp, nil, parser.ParseComments)
		if err != nil {
			continue
		}
		if sf.Name != nil && f.Name != nil && sf.Name.Name == f.Name.Name {
			collectTypes(sf, types)
		}
	}

	r := &Result{
		Header: &Header{Package: f.Name.Name},
	}
	for _, imp := range f.Imports {
		name := ""
		if imp.Name != nil {
			name = imp.Name.Name
		}
		path := strings.Trim(imp.Path.Value, "\"")
		r.Header.Imports = append(r.Header.Imports, &Import{Name: name, Path: path})
	}

	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if fd.Name.Name == "init" {
			continue
		}
		fn := parseFunc(fd, types)
		if fn == nil {
			continue
		}
		r.Functions = append(r.Functions, fn)
	}
	return r, nil
}

func collectTypes(f *ast.File, out map[string]*typeInfo) {
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.TYPE {
			continue
		}
		for _, s := range gd.Specs {
			ts, ok := s.(*ast.TypeSpec)
			if !ok {
				continue
			}
			ti := &typeInfo{Name: ts.Name.Name}
			if ts.TypeParams != nil {
				for _, field := range ts.TypeParams.List {
					constraint := exprString(field.Type)
					concrete := concreteForConstraint(field.Type)
					for _, n := range field.Names {
						ti.TypeParams = append(ti.TypeParams, &models.TypeParam{
							Name:       n.Name,
							Constraint: constraint,
							Concrete:   concrete,
						})
					}
				}
			}
			if st, ok := ts.Type.(*ast.StructType); ok {
				ti.Struct = st
			}
			out[ts.Name.Name] = ti
		}
	}
}

func parseFunc(fd *ast.FuncDecl, types map[string]*typeInfo) *models.Function {
	fn := &models.Function{
		Name:       fd.Name.Name,
		IsExported: ast.IsExported(fd.Name.Name),
	}

	// Type parameters on the function
	if fd.Type.TypeParams != nil {
		for _, field := range fd.Type.TypeParams.List {
			constraint := exprString(field.Type)
			concrete := concreteForConstraint(field.Type)
			for _, n := range field.Names {
				fn.TypeParams = append(fn.TypeParams, &models.TypeParam{
					Name: n.Name, Constraint: constraint, Concrete: concrete,
				})
			}
		}
	}

	typeParamMap := map[string]string{}
	for _, tp := range fn.TypeParams {
		typeParamMap[tp.Name] = tp.Concrete
	}

	// Receiver
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		rf := fd.Recv.List[0]
		rcv := &models.Receiver{}
		rname := ""
		if len(rf.Names) > 0 && rf.Names[0].Name != "" && rf.Names[0].Name != "_" {
			rname = rf.Names[0].Name
		}
		baseTypeName, isStar, typeArgs := receiverTypeInfo(rf.Type)

		ti := types[baseTypeName]
		isGeneric := len(typeArgs) > 0

		// Determine concrete args from the type's declaration
		concreteArgs := make([]string, len(typeArgs))
		if ti != nil {
			for i := range typeArgs {
				if i < len(ti.TypeParams) {
					concreteArgs[i] = ti.TypeParams[i].Concrete
				} else {
					concreteArgs[i] = "int"
				}
			}
		} else {
			for i := range typeArgs {
				concreteArgs[i] = "int"
			}
		}

		typeName := baseTypeName
		if len(typeArgs) > 0 {
			typeName = baseTypeName + "[" + strings.Join(typeArgs, ", ") + "]"
		}
		concreteTypeName := baseTypeName
		if len(concreteArgs) > 0 {
			concreteTypeName = baseTypeName + "[" + strings.Join(concreteArgs, ", ") + "]"
		}

		// Populate typeParamMap with receiver's type args (T -> int)
		for i, a := range typeArgs {
			if i < len(concreteArgs) {
				typeParamMap[a] = concreteArgs[i]
			}
		}

		pfx := ""
		if isStar {
			pfx = "*"
		}
		rcv.Type = &models.Expression{
			Value:  pfx + concreteTypeName,
			IsStar: isStar,
		}
		if rname == "" {
			rname = defaultReceiverName(baseTypeName)
		}
		if rname == "t" {
			rname = "tr"
		}
		rcv.Name = rname
		// For generic types, treat receiver as non-struct for fields display
		isStruct := ti != nil && ti.Struct != nil && !isGeneric
		rcv.IsStruct = isStruct
		rcv.TypeName = typeName
		rcv.ConcreteTypeName = concreteTypeName
		if isStruct && ti != nil && ti.Struct != nil && ti.Struct.Fields != nil {
			for _, f := range ti.Struct.Fields.List {
				typStr := exprString(f.Type)
				if len(f.Names) == 0 {
					rcv.Fields = append(rcv.Fields, &models.Field{
						Name: typStr,
						Type: &models.Expression{Value: typStr},
					})
					continue
				}
				for _, n := range f.Names {
					rcv.Fields = append(rcv.Fields, &models.Field{
						Name: n.Name,
						Type: &models.Expression{Value: typStr},
					})
				}
			}
		}
		fn.Receiver = rcv
	}

	// Parameters
	blankIdx := 0
	if fd.Type.Params != nil {
		for _, field := range fd.Type.Params.List {
			origTypeStr := exprString(field.Type)
			isVariadic := false
			actualType := field.Type
			if el, ok := field.Type.(*ast.Ellipsis); ok {
				actualType = el.Elt
				isVariadic = true
				origTypeStr = exprString(actualType)
			}
			concreteType := substituteTypeParams(origTypeStr, typeParamMap)

			if len(field.Names) == 0 {
				fn.Parameters = append(fn.Parameters, &models.Field{
					Name: fmt.Sprintf("in%d", blankIdx),
					Type: &models.Expression{Value: concreteType, IsVariadic: isVariadic},
				})
				blankIdx++
				continue
			}
			for _, n := range field.Names {
				name := n.Name
				if name == "_" {
					name = fmt.Sprintf("in%d", blankIdx)
					blankIdx++
				}
				fn.Parameters = append(fn.Parameters, &models.Field{
					Name: name,
					Type: &models.Expression{Value: concreteType, IsVariadic: isVariadic},
				})
			}
		}
	}

	// Results
	if fd.Type.Results != nil {
		i := 0
		for _, field := range fd.Type.Results.List {
			origTypeStr := exprString(field.Type)
			concreteType := substituteTypeParams(origTypeStr, typeParamMap)
			if len(field.Names) == 0 {
				fn.Results = append(fn.Results, &models.Field{
					Name:  "",
					Type:  &models.Expression{Value: concreteType},
					Index: i,
				})
				i++
				continue
			}
			for _, n := range field.Names {
				name := n.Name
				isNamed := name != "" && name != "_"
				if name == "_" {
					name = ""
					isNamed = false
				}
				fn.Results = append(fn.Results, &models.Field{
					Name:    name,
					Type:    &models.Expression{Value: concreteType},
					IsNamed: isNamed,
					Index:   i,
				})
				i++
			}
		}
	}

	// Check for error return (last position)
	if n := len(fn.Results); n > 0 {
		last := fn.Results[n-1]
		if last.Type.Value == "error" {
			fn.ReturnsError = true
			fn.Results = fn.Results[:n-1]
			if n-1 == 0 {
				fn.ReturnsOnlyError = true
			}
		}
	}

	return fn
}

func receiverTypeInfo(e ast.Expr) (base string, isStar bool, typeArgs []string) {
	switch t := e.(type) {
	case *ast.StarExpr:
		b, _, ta := receiverTypeInfo(t.X)
		return b, true, ta
	case *ast.Ident:
		return t.Name, false, nil
	case *ast.IndexExpr:
		b, _, _ := receiverTypeInfo(t.X)
		return b, false, []string{exprString(t.Index)}
	case *ast.IndexListExpr:
		b, _, _ := receiverTypeInfo(t.X)
		var args []string
		for _, a := range t.Indices {
			args = append(args, exprString(a))
		}
		return b, false, args
	}
	return "", false, nil
}

func defaultReceiverName(typeName string) string {
	if typeName == "" {
		return "t"
	}
	c := typeName[0]
	if c >= 'A' && c <= 'Z' {
		c += 'a' - 'A'
	}
	name := string(c)
	if name == "t" {
		return "tr"
	}
	return name
}

// concreteForConstraint returns the default concrete type for a constraint expression.
func concreteForConstraint(e ast.Expr) string {
	s := strings.TrimSpace(exprString(e))
	if s == "any" || s == "interface{}" {
		return "int"
	}
	if s == "comparable" {
		return "string"
	}
	// Handle interface{ A | B } union types - look inside interface
	if strings.HasPrefix(s, "interface{") && strings.HasSuffix(s, "}") {
		inner := strings.TrimSuffix(strings.TrimPrefix(s, "interface{"), "}")
		inner = strings.TrimSpace(inner)
		return concreteFromUnionString(inner)
	}
	// Union types
	if strings.Contains(s, "|") {
		return concreteFromUnionString(s)
	}
	// Approximation constraint ~T
	if strings.HasPrefix(s, "~") {
		return strings.TrimPrefix(s, "~")
	}
	return s
}

func concreteFromUnionString(s string) string {
	parts := strings.Split(s, "|")
	first := strings.TrimSpace(parts[0])
	first = strings.TrimPrefix(first, "~")
	return first
}

func substituteTypeParams(typeStr string, m map[string]string) string {
	if len(m) == 0 {
		return typeStr
	}
	var out strings.Builder
	i := 0
	for i < len(typeStr) {
		c := typeStr[i]
		if isIdentStart(c) {
			j := i + 1
			for j < len(typeStr) && isIdentPart(typeStr[j]) {
				j++
			}
			word := typeStr[i:j]
			if v, ok := m[word]; ok {
				out.WriteString(v)
			} else {
				out.WriteString(word)
			}
			i = j
		} else {
			out.WriteByte(c)
			i++
		}
	}
	return out.String()
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentPart(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func exprString(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	case *ast.ArrayType:
		lenStr := ""
		if t.Len != nil {
			lenStr = exprString(t.Len)
		}
		return "[" + lenStr + "]" + exprString(t.Elt)
	case *ast.MapType:
		return "map[" + exprString(t.Key) + "]" + exprString(t.Value)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			return "chan<- " + exprString(t.Value)
		case ast.RECV:
			return "<-chan " + exprString(t.Value)
		default:
			return "chan " + exprString(t.Value)
		}
	case *ast.FuncType:
		return "func" + funcSigString(t)
	case *ast.InterfaceType:
		if t.Methods == nil || len(t.Methods.List) == 0 {
			return "interface{}"
		}
		var parts []string
		for _, m := range t.Methods.List {
			if len(m.Names) == 0 {
				parts = append(parts, exprString(m.Type))
			} else if ft, ok := m.Type.(*ast.FuncType); ok {
				parts = append(parts, m.Names[0].Name+funcSigString(ft))
			}
		}
		return "interface{ " + strings.Join(parts, "; ") + " }"
	case *ast.StructType:
		if t.Fields == nil || len(t.Fields.List) == 0 {
			return "struct{}"
		}
		var parts []string
		for _, f := range t.Fields.List {
			ts := exprString(f.Type)
			if len(f.Names) == 0 {
				parts = append(parts, ts)
			} else {
				var names []string
				for _, n := range f.Names {
					names = append(names, n.Name)
				}
				parts = append(parts, strings.Join(names, ", ")+" "+ts)
			}
		}
		return "struct{ " + strings.Join(parts, "; ") + " }"
	case *ast.Ellipsis:
		return "..." + exprString(t.Elt)
	case *ast.IndexExpr:
		return exprString(t.X) + "[" + exprString(t.Index) + "]"
	case *ast.IndexListExpr:
		var args []string
		for _, a := range t.Indices {
			args = append(args, exprString(a))
		}
		return exprString(t.X) + "[" + strings.Join(args, ", ") + "]"
	case *ast.BinaryExpr:
		return exprString(t.X) + " " + t.Op.String() + " " + exprString(t.Y)
	case *ast.UnaryExpr:
		return t.Op.String() + exprString(t.X)
	case *ast.BasicLit:
		return t.Value
	case *ast.ParenExpr:
		return "(" + exprString(t.X) + ")"
	}
	return fmt.Sprintf("/*%T*/", e)
}

func funcSigString(ft *ast.FuncType) string {
	var b strings.Builder
	b.WriteByte('(')
	if ft.Params != nil {
		first := true
		for _, f := range ft.Params.List {
			ts := exprString(f.Type)
			if len(f.Names) == 0 {
				if !first {
					b.WriteString(", ")
				}
				b.WriteString(ts)
				first = false
			} else {
				for _, n := range f.Names {
					if !first {
						b.WriteString(", ")
					}
					b.WriteString(n.Name + " " + ts)
					first = false
				}
			}
		}
	}
	b.WriteByte(')')
	if ft.Results != nil {
		count := 0
		hasNames := false
		for _, f := range ft.Results.List {
			if len(f.Names) == 0 {
				count++
			} else {
				count += len(f.Names)
				hasNames = true
			}
		}
		if count == 1 && !hasNames {
			b.WriteByte(' ')
			b.WriteString(exprString(ft.Results.List[0].Type))
		} else if count > 0 {
			b.WriteString(" (")
			first := true
			for _, f := range ft.Results.List {
				ts := exprString(f.Type)
				if len(f.Names) == 0 {
					if !first {
						b.WriteString(", ")
					}
					b.WriteString(ts)
					first = false
				} else {
					for _, n := range f.Names {
						if !first {
							b.WriteString(", ")
						}
						b.WriteString(n.Name + " " + ts)
						first = false
					}
				}
			}
			b.WriteString(")")
		}
	}
	return b.String()
}
