	case *ast.BinaryExpr:
		return exprString(t.X) + " " + t.Op.String() + " " + exprString(t.Y)
	case *ast.UnaryExpr:
		return t.Op.String() + exprString(t.X)
	case *ast.BasicLit:
		return t.Value
	case *ast.ParenExpr:
		return "(" + exprString(t.X) + ")"
	}
	return fmt.Sprintf("/*%T*/", e)
}

func funcSigString(ft *ast.FuncType) string {
	var b strings.Builder
	b.WriteByte('(')
	if ft.Params != nil {
		first := true
		for _, f := range ft.Params.List {
			ts := exprString(f.Type)
			if len(f.Names) == 0 {
				if !first {
					b.WriteString(", ")
				}
				b.WriteString(ts)
				first = false
			} else {
				for _, n := range f.Names {
					if !first {
						b.WriteString(", ")
					}
					b.WriteString(n.Name + " " + ts)
					first = false
				}
			}
		}
	}
	b.WriteByte(')')
	if ft.Results != nil {
		count := 0
		hasNames := false
		for _, f := range ft.Results.List {
			if len(f.Names) == 0 {
				count++
			} else {
				count += len(f.Names)
				hasNames = true
			}
		}
		if count == 1 && !hasNames {
			b.WriteByte(' ')
			b.WriteString(exprString(ft.Results.List[0].Type))
		} else if count > 0 {
			b.WriteString(" (")
			first := true
			for _, f := range ft.Results.List {
				ts := exprString(f.Type)
				if len(f.Names) == 0 {
					if !first {
						b.WriteString(", ")
					}
					b.WriteString(ts)
					first = false
				} else {
					for _, n := range f.Names {
						if !first {
							b.WriteString(", ")
						}
						b.WriteString(n.Name + " " + ts)
						first = false
					}
				}
			}
			b.WriteString(")")
		}
	}
	return b.String()
}
