	isStd := func(p string) bool {
		i := strings.Index(p, "/")
		first := p
		if i >= 0 {
			first = p[:i]
		}
		return !strings.Contains(first, ".")
	}
	var stdlib, external []Import
	for _, im := range imps {
		if isStd(im.Path) {
			stdlib = append(stdlib, im)
		} else {
