		} else if res.Index == 0 {
			nm = "want"
		} else {
			nm = fmt.Sprintf("want%d", res.Index)
		}
		fmt.Fprintf(out, "\t\t%s    %s\n", nm, res.Type.Value)
	}
	// wantErr or assertion
	if fn.ReturnsError {
		if r.opts.Template == "testify" {
			out.WriteString("\t\tassertion assert.ErrorAssertionFunc\n")
		} else {
			out.WriteString("\t\twantErr bool\n")
		}
	}
	out.WriteString("\t}{\n")
	out.WriteString("\t\t// TODO: Add test cases.\n")
	out.WriteString("\t}\n")

