// Render generates test code for the given functions.
func Render(pkg string, headerImports []Import, funcs []*models.Function, opts Options) []byte {
	var out bytes.Buffer
	useReflect := false
	useCmp := false
	useTestify := opts.Template == "testify"

	// First render the tests to a buffer so we know what imports are needed.
	var body bytes.Buffer
	for _, fn := range funcs {
		r := &funcRenderer{fn: fn, opts: opts}
		r.render(&body)
		body.WriteString("\n")
		if r.usedReflect {
			useReflect = true
		}
		if r.usedCmp {
			useCmp = true
		}
	}

	// Build package header
	out.WriteString("package ")
	out.WriteString(pkg)
	out.WriteString("\n\n")

	// Imports
	writeImports(&out, headerImports, useReflect, useCmp, useTestify)
	out.WriteString("\n")

	out.Write(body.Bytes())
	return out.Bytes()
}

// Import represents an import statement.
type Import struct {
	Name string
	Path string
}

func writeImports(out *bytes.Buffer, base []Import, useReflect, useCmp, useTestify bool) {
	var imps []Import
	imps = append(imps, base...)
	// Add testing
	if !hasImport(imps, "", "testing") {
		imps = append(imps, Import{Path: "testing"})
	}
