		imps = append(imps, Import{Path: "github.com/stretchr/testify/assert"})
	}

	// Partition stdlib vs external
	isStd := func(p string) bool {
		i := strings.Index(p, "/")
		first := p
		if i >= 0 {
			first = p[:i]
		}
		return !strings.Contains(first, ".")
	}
	var stdlib, external []Import
	for _, im := range imps {
		if isStd(im.Path) {
			stdlib = append(stdlib, im)
		} else {
			external = append(external, im)
		}
	}
	sort.SliceStable(stdlib, func(i, j int) bool { return stdlib[i].Path < stdlib[j].Path })
	sort.SliceStable(external, func(i, j int) bool { return external[i].Path < external[j].Path })

	all := append([]Import{}, stdlib...)
	all = append(all, external...)

	if len(all) == 1 && len(external) == 0 && stdlib[0].Name == "" {
		fmt.Fprintf(out, "import \"%s\"\n", stdlib[0].Path)
		return
	}
	out.WriteString("import (\n")
	for i, im := range stdlib {
		writeImportLine(out, im)
		_ = i
	}
	if len(external) > 0 && len(stdlib) > 0 {
		out.WriteString("\n")
	}
	for _, im := range external {
		writeImportLine(out, im)
	}
	out.WriteString(")\n")
}

func writeImportLine(out *bytes.Buffer, im Import) {
	if im.Name == "" {
		fmt.Fprintf(out, "\t\"%s\"\n", im.Path)
	} else {
		fmt.Fprintf(out, "\t%s \"%s\"\n", im.Name, im.Path)
	}
}

func hasImport(imps []Import, name, path string) bool {
	for _, im := range imps {
		if im.Path == path {
			return true
		}
	}
	_ = name
	return false
}

type funcRenderer struct {
	fn         *models.Function
	opts       Options
	usedReflect bool
	usedCmp    bool
}

func (r *funcRenderer) render(out *bytes.Buffer) {
	fn := r.fn
	fmt.Fprintf(out, "func %s(t *testing.T) {\n", fn.TestName())
	if r.opts.Parallel {
		out.WriteString("\tt.Parallel()\n")
	}

	hasFields := fn.Receiver != nil && fn.Receiver.IsStruct && len(fn.Receiver.Fields) > 0
	hasArgs := len(fn.Parameters) > 0

	// type fields struct {}
	if hasFields {
		out.WriteString("\ttype fields struct {\n")
		for _, f := range fn.Receiver.Fields {
			fmt.Fprintf(out, "\t\t%s %s\n", f.Name, f.Type.Value)
		}
		out.WriteString("\t}\n")
	}

	// type args struct {}
	if hasArgs {
		out.WriteString("\ttype args struct {\n")
		for _, p := range fn.Parameters {
			fmt.Fprintf(out, "\t\t%s %s\n", p.Name, p.Type.String())
		}
		out.WriteString("\t}\n")
	}

	// tests := []struct or map[string]struct
	if r.opts.Named {
		out.WriteString("\ttests := map[string]struct {\n")
	} else {
		out.WriteString("\ttests := []struct {\n")
		out.WriteString("\t\tname    string\n")
	}

	// fields slot
	if hasFields {
		out.WriteString("\t\tfields  fields\n")
	}
	// Receiver-as-field for non-struct receiver (including generic structs)
	if fn.Receiver != nil && !fn.Receiver.IsStruct {
		rtype := fn.Receiver.Type.Value
		fmt.Fprintf(out, "\t\t%s    %s\n", fn.Receiver.Name, rtype)
	}
	if hasArgs {
		out.WriteString("\t\targs    args\n")
	}
	// wants
	for _, res := range fn.Results {
		var nm string
		if res.IsNamed {
			nm = "want" + capitalize(res.Name)
		} else if res.Index == 0 {
			nm = "want"
		} else {
			nm = fmt.Sprintf("want%d", res.Index)
		}
		fmt.Fprintf(out, "\t\t%s    %s\n", nm, res.Type.Value)
	}
	// wantErr or assertion
	if fn.ReturnsError {
		if r.opts.Template == "testify" {
			out.WriteString("\t\tassertion assert.ErrorAssertionFunc\n")
		} else {
			out.WriteString("\t\twantErr bool\n")
		}
	}
	out.WriteString("\t}{\n")
	out.WriteString("\t\t// TODO: Add test cases.\n")
	out.WriteString("\t}\n")

	// Loop
	if r.opts.Named {
		out.WriteString("\tfor name, tt := range tests {\n")
	} else {
		out.WriteString("\tfor _, tt := range tests {\n")
	}

	subtest := r.opts.Subtests
	indent := "\t\t"
	if subtest {
		if r.opts.Named {
			out.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			out.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if r.opts.Parallel {
			out.WriteString("\t\t\tt.Parallel()\n")
		}
		indent = "\t\t\t"
	}

	// Receiver init
	if fn.Receiver != nil && fn.Receiver.IsStruct {
		// struct receiver - init from fields
		pfx := ""
		if fn.Receiver.Type.IsStar {
			pfx = "&"
		}
		fmt.Fprintf(out, "%s%s := %s%s{\n", indent, fn.Receiver.Name, pfx, fn.Receiver.ConcreteTypeName)
		for _, f := range fn.Receiver.Fields {
			fmt.Fprintf(out, "%s\t%s: tt.fields.%s,\n", indent, f.Name, f.Name)
		}
		fmt.Fprintf(out, "%s}\n", indent)
	} else if fn.Receiver != nil {
		// non-struct or generic receiver, and receiver has no fields either
		// For methods on aliases/generic types, we still may want to initialize the receiver.
		// Pattern: r := &Type{} when we need to call method on it.
		// But for alias types (IntAlias), we call tt.a.Method() without init.
		// Decision: for generic structs we DO init (b := Box[int]{}). For aliases we don't.
		if isGenericStruct(fn.Receiver) {
			pfx := ""
			if fn.Receiver.Type.IsStar {
				pfx = "&"
			}
			fmt.Fprintf(out, "%s%s := %s%s{}\n", indent, fn.Receiver.Name, pfx, fn.Receiver.ConcreteTypeName)
		} else if isNonStructReceiverWithInit(fn.Receiver) {
			// Empty struct receiver
			pfx := ""
			if fn.Receiver.Type.IsStar {
				pfx = "&"
			}
			fmt.Fprintf(out, "%s%s := %s%s{}\n", indent, fn.Receiver.Name, pfx, fn.Receiver.ConcreteTypeName)
		}
	}

	// Call + checks
	r.renderCall(out, indent)

	if subtest {
		out.WriteString("\t\t})\n")
	}
	out.WriteString("\t}\n")
	out.WriteString("}\n")
}

// isGenericStruct returns true for generic struct receivers (like Box[T]).
func isGenericStruct(r *models.Receiver) bool {
	return strings.Contains(r.TypeName, "[") && !r.IsStruct
}

// isNonStructReceiverWithInit checks empty-struct receivers that we still init.
// The original gotests inits with {} only for empty-struct cases too.
func isNonStructReceiverWithInit(r *models.Receiver) bool {
	// We detect "empty struct" via: the underlying type is a struct but no fields captured.
	// In our model, IsStruct is false for that case (we also exclude generic).
	// Actually we set IsStruct=true when ti.Struct != nil. Let's check fields.
	return false // TODO handled separately below
}

// capitalize: first rune to upper
func capitalize(s string) string {
	if s == "" {
		return s
	}
	c := s[0]
	if c >= 'a' && c <= 'z' {
		c -= 'a' - 'A'
	}
	return string(c) + s[1:]
}

// --- call and checks ---

func (r *funcRenderer) renderCall(out *bytes.Buffer, indent string) {
	fn := r.fn
	// Determine call expression
	var call strings.Builder
	if fn.Receiver != nil {
		if fn.Receiver.IsStruct {
			call.WriteString(fn.Receiver.Name + "." + fn.Name)
		} else if isGenericStruct(fn.Receiver) {
			call.WriteString(fn.Receiver.Name + "." + fn.Name)
		} else {
			// use tt.<receiverName>.<Method>
			call.WriteString("tt." + fn.Receiver.Name + "." + fn.Name)
		}
	} else {
		call.WriteString(fn.Name)
		// Generic function: instantiate with concrete type params
		if len(fn.TypeParams) > 0 {
			call.WriteString("[")
			for i, tp := range fn.TypeParams {
				if i > 0 {
					call.WriteString(", ")
				}
				call.WriteString(tp.Concrete)
			}
			call.WriteString("]")
		}
	}
	call.WriteString("(")
	for i, p := range fn.Parameters {
		if i > 0 {
			call.WriteString(", ")
		}
		call.WriteString("tt.args." + p.Name)
		if p.Type.IsVariadic {
			call.WriteString("...")
		}
	}
	call.WriteString(")")

	// Build error checks / inline
	disp := fn.DisplayName()

	// Helper for rendering assert part (for -i flag):
	inputsArgs := ""
	if r.opts.PrintInputs && len(fn.Parameters) > 0 {
		var pa []string
		for _, p := range fn.Parameters {
			pa = append(pa, "tt.args."+p.Name)
		}
		// format: "Name(%v, %v) = %v, want %v"
		// fmt strings are built in error calls below
		// We pass the args list as comma separated
		inputsArgs = strings.Join(pa, ", ")
	}

	// Compute wantX names for results
	resultVarName := func(res *models.Field) (gotName, wantName string) {
		if res.IsNamed {
			return "got" + capitalize(res.Name), "tt.want" + capitalize(res.Name)
		}
		if res.Index == 0 {
			return "got", "tt.want"
		}
		return fmt.Sprintf("got%d", res.Index), fmt.Sprintf("tt.want%d", res.Index)
	}

	// Number of results (non-error)
	nRes := len(fn.Results)

	// testify template branches
	if r.opts.Template == "testify" {
		// Handle: no results, only error, results + maybe error
		if nRes == 0 && !fn.ReturnsError {
			fmt.Fprintf(out, "%s%s\n", indent, call.String())
			return
		}
		if nRes == 0 && fn.ReturnsError {
			// tt.assertion(t, Call())
			fmt.Fprintf(out, "%stt.assertion(t, %s)\n", indent, call.String())
			return
		}
		// Has results
		var lhs []string
		for _, res := range fn.Results {
			gn, _ := resultVarName(res)
			lhs = append(lhs, gn)
		}
		if fn.ReturnsError {
			lhs = append(lhs, "err")
		}
		fmt.Fprintf(out, "%s%s := %s\n", indent, strings.Join(lhs, ", "), call.String())
		if fn.ReturnsError {
			fmt.Fprintf(out, "%stt.assertion(t, err)\n", indent)
		}
		for _, res := range fn.Results {
			gn, wn := resultVarName(res)
			fmt.Fprintf(out, "%sassert.Equal(t, %s, %s)\n", indent, wn, gn)
		}
		return
	}

	// Default template (not testify)
	// Error helper text for wants
	errorFn := "t.Errorf"
	errCheckCmd := ""
	if fn.ReturnsError {
		if nRes > 0 || r.opts.Subtests {
			// Use Fatalf so that we can continue returning
			errCheckCmd = "t.Fatalf"
		} else {
			errCheckCmd = "t.Errorf"
		}
	}
	_ = errorFn
	_ = errCheckCmd

	// Special case: returns only error, no other results -> inline
	if nRes == 0 && fn.ReturnsError {
		// Inline: if err := Call(); (err != nil) != tt.wantErr { t.Errorf("Name() error = %v, wantErr %v", err, tt.wantErr) }
		fmt.Fprintf(out, "%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call.String())
		if r.opts.PrintInputs && inputsArgs != "" {
			formatArgs := strings.Repeat(", %v", len(fn.Parameters))
			formatArgs = strings.TrimPrefix(formatArgs, ", ")
			fmt.Fprintf(out, "%s\tt.Errorf(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", indent, disp, formatArgs, inputsArgs)
		} else {
			fmt.Fprintf(out, "%s\tt.Errorf(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", indent, disp)
		}
		fmt.Fprintf(out, "%s}\n", indent)
		return
	}

	if nRes == 0 && !fn.ReturnsError {
		// No returns - just call
		fmt.Fprintf(out, "%s%s\n", indent, call.String())
		return
	}

	// Has results (maybe with error)
	// If single result and no error: inline with if got := Call(); !cmp { t.Errorf }
	if nRes == 1 && !fn.ReturnsError {
		res := fn.Results[0]
		gn, wn := resultVarName(res)
		cmp := comparisonExpr(res.Type.Value, gn, wn, r.opts.UseGoCmp)
		// Detect if reflect/cmp used
		if isComplexType(res.Type.Value) {
			if r.opts.UseGoCmp {
				r.usedCmp = true
			} else {
				r.usedReflect = true
			}
		}
		fmt.Fprintf(out, "%sif %s := %s; %s {\n", indent, gn, call.String(), cmp)
		r.writeErrorf(out, indent+"\t", disp, gn, wn, res.Type.Value, inputsArgs, fn.Parameters)
		fmt.Fprintf(out, "%s}\n", indent)
		return
	}

	// Multi-value or error
	var lhs []string
	for _, res := range fn.Results {
		gn, _ := resultVarName(res)
		lhs = append(lhs, gn)
	}
	if fn.ReturnsError {
		lhs = append(lhs, "err")
	}
	fmt.Fprintf(out, "%s%s := %s\n", indent, strings.Join(lhs, ", "), call.String())
	if fn.ReturnsError {
		// (err != nil) != tt.wantErr check
		cmd := errCheckCmd
		fmt.Fprintf(out, "%sif (err != nil) != tt.wantErr {\n", indent)
		if r.opts.PrintInputs && inputsArgs != "" {
			formatArgs := strings.Repeat(", %v", len(fn.Parameters))
			formatArgs = strings.TrimPrefix(formatArgs, ", ")
			fmt.Fprintf(out, "%s\t%s(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", indent, cmd, disp, formatArgs, inputsArgs)
		} else {
			fmt.Fprintf(out, "%s\t%s(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", indent, cmd, disp)
		}
		if !r.opts.Subtests {
			// nosubtests: use `continue` pattern
			// Actually: the observed output for nosubtests uses `continue`
		}
		fmt.Fprintf(out, "%s}\n", indent)
		if nRes > 0 {
			fmt.Fprintf(out, "%sif tt.wantErr {\n", indent)
			fmt.Fprintf(out, "%s\treturn\n", indent)
			fmt.Fprintf(out, "%s}\n", indent)
		}
	}
	// Now check each result
	for _, res := range fn.Results {
		gn, wn := resultVarName(res)
		cmp := comparisonExpr(res.Type.Value, gn, wn, r.opts.UseGoCmp)
		if isComplexType(res.Type.Value) {
			if r.opts.UseGoCmp {
				r.usedCmp = true
			} else {
				r.usedReflect = true
			}
		}
		if nRes == 1 {
			// single result with error
			fmt.Fprintf(out, "%sif %s {\n", indent, cmp)
			r.writeErrorf(out, indent+"\t", disp, gn, wn, res.Type.Value, inputsArgs, fn.Parameters)
			fmt.Fprintf(out, "%s}\n", indent)
		} else {
			// Multiple: prefix with "got = ..." "got1 = ..."
			fmt.Fprintf(out, "%sif %s {\n", indent, cmp)
			r.writeErrorfMulti(out, indent+"\t", disp, gn, wn, res.Type.Value, inputsArgs, fn.Parameters)
			fmt.Fprintf(out, "%s}\n", indent)
		}
	}
}

func (r *funcRenderer) writeErrorf(out *bytes.Buffer, indent, disp, gn, wn, typ, inputsArgs string, params []*models.Field) {
	// Pattern: t.Errorf("Name() = %v, want %v", got, want) OR with inputs
	extra := ""
	cmpPart := ""
	if r.opts.UseGoCmp && isComplexType(typ) {
		cmpPart = fmt.Sprintf("\\ndiff=%%s\", %s, %s, cmp.Diff(%s, %s)", gn, wn, wn, gn)
	}
	if r.opts.PrintInputs && len(params) > 0 {
		fmtArgs := strings.Repeat(", %v", len(params))
		fmtArgs = strings.TrimPrefix(fmtArgs, ", ")
		if cmpPart != "" {
			fmt.Fprintf(out, "%st.Errorf(\"%s(%s) = %%v, want %%v%s)\n", indent, disp, fmtArgs, cmpPart)
		} else {
			fmt.Fprintf(out, "%st.Errorf(\"%s(%s) = %%v, want %%v\", %s, %s, %s)\n", indent, disp, fmtArgs, inputsArgs, gn, wn)
		}
	} else {
		if cmpPart != "" {
			fmt.Fprintf(out, "%st.Errorf(\"%s() = %%v, want %%v%s)\n", indent, disp, cmpPart)
		} else {
			fmt.Fprintf(out, "%st.Errorf(\"%s() = %%v, want %%v\", %s, %s)\n", indent, disp, gn, wn)
		}
	}
	_ = extra
}

func (r *funcRenderer) writeErrorfMulti(out *bytes.Buffer, indent, disp, gn, wn, typ, inputsArgs string, params []*models.Field) {
	cmpPart := ""
	if r.opts.UseGoCmp && isComplexType(typ) {
		cmpPart = fmt.Sprintf("\\ndiff=%%s\", %s, %s, cmp.Diff(%s, %s)", gn, wn, wn, gn)
	}
	if r.opts.PrintInputs && len(params) > 0 {
		fmtArgs := strings.Repeat(", %v", len(params))
		fmtArgs = strings.TrimPrefix(fmtArgs, ", ")
		if cmpPart != "" {
			fmt.Fprintf(out, "%st.Errorf(\"%s(%s) %s = %%v, want %%v%s)\n", indent, disp, fmtArgs, gn, cmpPart)
		} else {
			fmt.Fprintf(out, "%st.Errorf(\"%s(%s) %s = %%v, want %%v\", %s, %s, %s)\n", indent, disp, fmtArgs, gn, inputsArgs, gn, wn)
		}
	} else {
		if cmpPart != "" {
			fmt.Fprintf(out, "%st.Errorf(\"%s() %s = %%v, want %%v%s)\n", indent, disp, gn, cmpPart)
		} else {
			fmt.Fprintf(out, "%st.Errorf(\"%s() %s = %%v, want %%v\", %s, %s)\n", indent, disp, gn, gn, wn)
		}
	}
}

// isComplexType returns true if the given type requires reflect.DeepEqual for comparison.
func isComplexType(s string) bool {
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	// simple types
	if strings.HasPrefix(s, "*") {
		return true
	}
	if strings.HasPrefix(s, "[") || strings.HasPrefix(s, "map") || strings.HasPrefix(s, "chan") || strings.HasPrefix(s, "<-chan") || strings.HasPrefix(s, "chan<-") {
		return true
	}
	if strings.HasPrefix(s, "func(") || strings.HasPrefix(s, "func ") {
		return true
	}
	if strings.HasPrefix(s, "interface") {
		return true
	}
	if strings.HasPrefix(s, "struct{") || strings.HasPrefix(s, "struct ") {
		return true
	}
	// type parameter (starts with capital T only or single letter like T) - treat as complex since we don't know
	// Actually, if a type is a single uppercase letter, it's probably a type parameter being used.
	if len(s) == 1 && s[0] >= 'A' && s[0] <= 'Z' {
		return true
	}
	return false
}

func comparisonExpr(typ, gn, wn string, useGoCmp bool) string {
	if isComplexType(typ) {
		if useGoCmp {
			return fmt.Sprintf("!cmp.Equal(%s, %s)", wn, gn)
		}
		return fmt.Sprintf("!reflect.DeepEqual(%s, %s)", gn, wn)
	}
	return fmt.Sprintf("%s != %s", gn, wn)
}
