func (r *funcRenderer) renderCall(out *bytes.Buffer, indent string) {
	fn := r.fn
	var call strings.Builder
	if fn.Receiver != nil {
		if isAliasReceiver(fn) {
			call.WriteString("tt." + fn.Receiver.Name + "." + fn.Name)
		} else {
			call.WriteString(fn.Receiver.Name + "." + fn.Name)
		}
	} else {
		call.WriteString(fn.Name)
		if len(fn.TypeParams) > 0 {
			call.WriteString("[")
			for i, tp := range fn.TypeParams {
				if i > 0 {
					call.WriteString(", ")
				}
				call.WriteString(tp.Concrete)
			}
			call.WriteString("]")
		}
	}
	call.WriteString("(")
	for i, p := range fn.Parameters {
		if i > 0 {
			call.WriteString(", ")
		}
		call.WriteString("tt.args." + p.Name)
		if p.Type.IsVariadic {
			call.WriteString("...")
		}
	}
	call.WriteString(")")

	disp := fn.DisplayName()

	// Inputs string for -i flag
	inputsArgs := ""
	if r.opts.PrintInputs && len(fn.Parameters) > 0 {
		var pa []string
		for _, p := range fn.Parameters {
			pa = append(pa, "tt.args."+p.Name)
		}
		inputsArgs = strings.Join(pa, ", ")
	}

	nRes := len(fn.Results)

	if r.opts.Template == "testify" {
		if nRes == 0 && !fn.ReturnsError {
			fmt.Fprintf(out, "%s%s\n", indent, call.String())
			return
		}
		if nRes == 0 && fn.ReturnsError {
			fmt.Fprintf(out, "%stt.assertion(t, %s)\n", indent, call.String())
			return
		}
		var lhs []string
		for _, res := range fn.Results {
			gn, _ := resultVarName(res)
			lhs = append(lhs, gn)
		}
		if fn.ReturnsError {
			lhs = append(lhs, "err")
		}
		// If no error, simpler:
		if !fn.ReturnsError && nRes == 1 {
			// assert.Equal(t, tt.want, Call())
			res := fn.Results[0]
			_, wn := resultVarName(res)
			fmt.Fprintf(out, "%sassert.Equal(t, %s, %s)\n", indent, wn, call.String())
			return
		}
		fmt.Fprintf(out, "%s%s := %s\n", indent, strings.Join(lhs, ", "), call.String())
		if fn.ReturnsError {
			fmt.Fprintf(out, "%stt.assertion(t, err)\n", indent)
		}
		for _, res := range fn.Results {
			gn, wn := resultVarName(res)
			fmt.Fprintf(out, "%sassert.Equal(t, %s, %s)\n", indent, wn, gn)
		}
		return
	}

	// Default template
	// error check command: Fatalf (if more results to check) else Errorf
	// But for -nosubtests, it uses continue instead.
	errCmd := "t.Errorf"
	if nRes > 0 && fn.ReturnsError {
		if r.opts.Subtests {
			errCmd = "t.Fatalf"
		} else {
			errCmd = "t.Errorf"
		}
	}

	// Case 1: only error
	if nRes == 0 && fn.ReturnsError {
		fmt.Fprintf(out, "%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call.String())
		r.writeErrorfErr(out, indent+"\t", "t.Errorf", disp, inputsArgs, fn.Parameters)
		fmt.Fprintf(out, "%s}\n", indent)
		return
	}

	// Case 2: no results, no error - just call
	if nRes == 0 && !fn.ReturnsError {
		fmt.Fprintf(out, "%s%s\n", indent, call.String())
		return
	}

	// Case 3: single result, no error - inline
	if nRes == 1 && !fn.ReturnsError {
		res := fn.Results[0]
		gn, wn := resultVarName(res)
		cmp := comparisonExpr(res.Type.Value, gn, wn, r.opts.UseGoCmp)
		if isComplexType(res.Type.Value) {
			if r.opts.UseGoCmp {
				r.usedCmp = true
			} else {
				r.usedReflect = true
			}
		}
		fmt.Fprintf(out, "%sif %s := %s; %s {\n", indent, gn, call.String(), cmp)
		r.writeErrorfVal(out, indent+"\t", "t.Errorf", disp, gn, wn, res.Type.Value, inputsArgs, fn.Parameters, false)
		fmt.Fprintf(out, "%s}\n", indent)
		return
	}

	// Multi-result (maybe with error)
	var lhs []string
	for _, res := range fn.Results {
		gn, _ := resultVarName(res)
		lhs = append(lhs, gn)
	}
	if fn.ReturnsError {
		lhs = append(lhs, "err")
	}
	fmt.Fprintf(out, "%s%s := %s\n", indent, strings.Join(lhs, ", "), call.String())
	if fn.ReturnsError {
		fmt.Fprintf(out, "%sif (err != nil) != tt.wantErr {\n", indent)
		r.writeErrorfErr(out, indent+"\t", errCmd, disp, inputsArgs, fn.Parameters)
		if !r.opts.Subtests {
			fmt.Fprintf(out, "%s\tcontinue\n", indent)
		}
		fmt.Fprintf(out, "%s}\n", indent)
		if nRes > 0 {
			fmt.Fprintf(out, "%sif tt.wantErr {\n%s\treturn\n%s}\n", indent, indent, indent)
		}
	}
	useMultiLabel := nRes > 1
	for _, res := range fn.Results {
		gn, wn := resultVarName(res)
		cmp := comparisonExpr(res.Type.Value, gn, wn, r.opts.UseGoCmp)
		if isComplexType(res.Type.Value) {
			if r.opts.UseGoCmp {
				r.usedCmp = true
			} else {
				r.usedReflect = true
			}
		}
		fmt.Fprintf(out, "%sif %s {\n", indent, cmp)
		r.writeErrorfVal(out, indent+"\t", "t.Errorf", disp, gn, wn, res.Type.Value, inputsArgs, fn.Parameters, useMultiLabel)
		fmt.Fprintf(out, "%s}\n", indent)
	}
}

func (r *funcRenderer) writeErrorfErr(out *bytes.Buffer, indent, cmd, disp, inputsArgs string, params []*models.Field) {
	if r.opts.PrintInputs && len(params) > 0 {
		fa := strings.TrimPrefix(strings.Repeat(", %v", len(params)), ", ")
		fmt.Fprintf(out, "%s%s(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", indent, cmd, disp, fa, inputsArgs)
	} else {
		fmt.Fprintf(out, "%s%s(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", indent, cmd, disp)
	}
}

func (r *funcRenderer) writeErrorfVal(out *bytes.Buffer, indent, cmd, disp, gn, wn, typ, inputsArgs string, params []*models.Field, multiLabel bool) {
	useCmp := r.opts.UseGoCmp && isComplexType(typ)
	labelPart := ""
	if multiLabel {
		labelPart = gn + " "
	}
	if r.opts.PrintInputs && len(params) > 0 {
		fa := strings.TrimPrefix(strings.Repeat(", %v", len(params)), ", ")
		if useCmp {
			fmt.Fprintf(out, "%s%s(\"%s(%s) %s= %%v, want %%v\\ndiff=%%s\", %s, %s, %s, cmp.Diff(%s, %s))\n",
				indent, cmd, disp, fa, labelPart, inputsArgs, gn, wn, wn, gn)
		} else {
			fmt.Fprintf(out, "%s%s(\"%s(%s) %s= %%v, want %%v\", %s, %s, %s)\n",
				indent, cmd, disp, fa, labelPart, inputsArgs, gn, wn)
		}
	} else {
		if useCmp {
			fmt.Fprintf(out, "%s%s(\"%s() %s= %%v, want %%v\\ndiff=%%s\", %s, %s, cmp.Diff(%s, %s))\n",
				indent, cmd, disp, labelPart, gn, wn, wn, gn)
		} else {
			fmt.Fprintf(out, "%s%s(\"%s() %s= %%v, want %%v\", %s, %s)\n",
				indent, cmd, disp, labelPart, gn, wn)
		}
	}
}

func isComplexType(s string) bool {
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	if strings.HasPrefix(s, "*") || strings.HasPrefix(s, "[") || strings.HasPrefix(s, "map") ||
		strings.HasPrefix(s, "chan") || strings.HasPrefix(s, "<-chan") || strings.HasPrefix(s, "chan<-") ||
		strings.HasPrefix(s, "func(") || strings.HasPrefix(s, "func ") ||
		strings.HasPrefix(s, "interface") || strings.HasPrefix(s, "struct{") || strings.HasPrefix(s, "struct ") {
		return true
	}
	// type param identifier (single uppercase)
	if len(s) == 1 && s[0] >= 'A' && s[0] <= 'Z' {
		return true
	}
	return false
}

func comparisonExpr(typ, gn, wn string, useGoCmp bool) string {
	if isComplexType(typ) {
		if useGoCmp {
			return fmt.Sprintf("!cmp.Equal(%s, %s)", wn, gn)
		}
		return fmt.Sprintf("!reflect.DeepEqual(%s, %s)", gn, wn)
	}
	return fmt.Sprintf("%s != %s", gn, wn)
}
