// Render generates test code.
func Render(pkg string, headerImports []Import, funcs []*models.Function, opts Options) []byte {
	var out bytes.Buffer

	var body bytes.Buffer
	useReflect := false
	useCmp := false
	useTestify := opts.Template == "testify"
	for _, fn := range funcs {
		r := &funcRenderer{fn: fn, opts: opts}
		r.render(&body)
		body.WriteString("\n")
		if r.usedReflect {
			useReflect = true
		}
		if r.usedCmp {
			useCmp = true
		}
	}

	out.WriteString("package ")
	out.WriteString(pkg)
	out.WriteString("\n\n")

	writeImports(&out, headerImports, useReflect, useCmp, useTestify)
	out.WriteString("\n")
	out.Write(body.Bytes())
	return out.Bytes()
}

// Import is a simple import record.
type Import struct {
	Name string
	Path string
}

func writeImports(out *bytes.Buffer, base []Import, useReflect, useCmp, useTestify bool) {
	imps := append([]Import{}, base...)
	if !hasImport(imps, "testing") {
		imps = append(imps, Import{Path: "testing"})
	}
	if useReflect && !hasImport(imps, "reflect") {
		imps = append(imps, Import{Path: "reflect"})
	}
	if useCmp && !hasImport(imps, "github.com/google/go-cmp/cmp") {
		imps = append(imps, Import{Path: "github.com/google/go-cmp/cmp"})
	}
	if useTestify && !hasImport(imps, "github.com/stretchr/testify/assert") {
		imps = append(imps, Import{Path: "github.com/stretchr/testify/assert"})
	}

	isStd := func(p string) bool {
		i := strings.Index(p, "/")
		first := p
		if i >= 0 {
			first = p[:i]
		}
		return !strings.Contains(first, ".")
	}
	var stdlib, external []Import
	for _, im := range imps {
		if isStd(im.Path) {
			stdlib = append(stdlib, im)
		} else {
			external = append(external, im)
		}
	}
	sort.SliceStable(stdlib, func(i, j int) bool { return stdlib[i].Path < stdlib[j].Path })
	sort.SliceStable(external, func(i, j int) bool { return external[i].Path < external[j].Path })

	if len(stdlib)+len(external) == 1 {
		var only Import
		if len(stdlib) > 0 {
			only = stdlib[0]
		} else {
			only = external[0]
		}
		if only.Name == "" {
			fmt.Fprintf(out, "import %q\n", only.Path)
		} else {
			fmt.Fprintf(out, "import %s %q\n", only.Name, only.Path)
		}
		return
	}
	out.WriteString("import (\n")
	for _, im := range stdlib {
		writeImportLine(out, im)
	}
	if len(external) > 0 && len(stdlib) > 0 {
		out.WriteString("\n")
	}
	for _, im := range external {
		writeImportLine(out, im)
	}
	out.WriteString(")\n")
}

func writeImportLine(out *bytes.Buffer, im Import) {
	if im.Name == "" {
