	return fn.Receiver != nil && fn.Receiver.IsStruct && len(fn.Receiver.Fields) == 0
}
func isGenericReceiver(fn *models.Function) bool {
	return fn.Receiver != nil && strings.Contains(fn.Receiver.TypeName, "[")
}
func isAliasReceiver(fn *models.Function) bool {
	return fn.Receiver != nil && !fn.Receiver.IsStruct && !isGenericReceiver(fn)
}

