package render

import (
	"bytes"
	"fmt"
	"sort"
	"strings"

	"gotests/internal/models"
)

// Options controls rendering behavior.
type Options struct {
	PrintInputs bool
	Subtests    bool
	Named       bool
	Parallel    bool
	UseGoCmp    bool
	Template    string
}

// Render generates test code.
func Render(pkg string, headerImports []Import, funcs []*models.Function, opts Options) []byte {
	var out bytes.Buffer

	var body bytes.Buffer
	useReflect := false
	useCmp := false
	useTestify := opts.Template == "testify"
	for _, fn := range funcs {
		r := &funcRenderer{fn: fn, opts: opts}
		r.render(&body)
		body.WriteString("\n")
		if r.usedReflect {
			useReflect = true
		}
		if r.usedCmp {
			useCmp = true
		}
	}

	out.WriteString("package ")
	out.WriteString(pkg)
	out.WriteString("\n\n")

	writeImports(&out, headerImports, useReflect, useCmp, useTestify)
	out.WriteString("\n")
	out.Write(body.Bytes())
	return out.Bytes()
}

// Import is a simple import record.
type Import struct {
	Name string
	Path string
}

func writeImports(out *bytes.Buffer, base []Import, useReflect, useCmp, useTestify bool) {
	imps := append([]Import{}, base...)
	if !hasImport(imps, "testing") {
		imps = append(imps, Import{Path: "testing"})
	}
	if useReflect && !hasImport(imps, "reflect") {
		imps = append(imps, Import{Path: "reflect"})
	}
	if useCmp && !hasImport(imps, "github.com/google/go-cmp/cmp") {
		imps = append(imps, Import{Path: "github.com/google/go-cmp/cmp"})
	}
	if useTestify && !hasImport(imps, "github.com/stretchr/testify/assert") {
		imps = append(imps, Import{Path: "github.com/stretchr/testify/assert"})
	}

	isStd := func(p string) bool {
		i := strings.Index(p, "/")
		first := p
		if i >= 0 {
			first = p[:i]
		}
		return !strings.Contains(first, ".")
	}
	var stdlib, external []Import
	for _, im := range imps {
		if isStd(im.Path) {
			stdlib = append(stdlib, im)
		} else {
			external = append(external, im)
		}
	}
	sort.SliceStable(stdlib, func(i, j int) bool { return stdlib[i].Path < stdlib[j].Path })
	sort.SliceStable(external, func(i, j int) bool { return external[i].Path < external[j].Path })

	if len(stdlib)+len(external) == 1 {
		var only Import
		if len(stdlib) > 0 {
			only = stdlib[0]
		} else {
			only = external[0]
		}
		if only.Name == "" {
			fmt.Fprintf(out, "import %q\n", only.Path)
		} else {
			fmt.Fprintf(out, "import %s %q\n", only.Name, only.Path)
		}
		return
	}
	out.WriteString("import (\n")
	for _, im := range stdlib {
		writeImportLine(out, im)
	}
	if len(external) > 0 && len(stdlib) > 0 {
		out.WriteString("\n")
	}
	for _, im := range external {
		writeImportLine(out, im)
	}
	out.WriteString(")\n")
}

func writeImportLine(out *bytes.Buffer, im Import) {
	if im.Name == "" {
		fmt.Fprintf(out, "\t%q\n", im.Path)
	} else {
		fmt.Fprintf(out, "\t%s %q\n", im.Name, im.Path)
	}
}

func hasImport(imps []Import, path string) bool {
	for _, im := range imps {
		if im.Path == path {
			return true
		}
	}
	return false
}

type funcRenderer struct {
	fn          *models.Function
	opts        Options
	usedReflect bool
	usedCmp     bool
}

// receiver classification helpers
func isStructReceiverWithFields(fn *models.Function) bool {
	return fn.Receiver != nil && fn.Receiver.IsStruct && len(fn.Receiver.Fields) > 0
}
func isEmptyStructReceiver(fn *models.Function) bool {
	return fn.Receiver != nil && fn.Receiver.IsStruct && len(fn.Receiver.Fields) == 0
}
func isGenericReceiver(fn *models.Function) bool {
	return fn.Receiver != nil && strings.Contains(fn.Receiver.TypeName, "[")
}
func isAliasReceiver(fn *models.Function) bool {
	return fn.Receiver != nil && !fn.Receiver.IsStruct && !isGenericReceiver(fn)
}

// receiver is listed as a top-level tests field
func receiverInTests(fn *models.Function) bool {
	return fn.Receiver != nil && (isEmptyStructReceiver(fn) || isGenericReceiver(fn) || isAliasReceiver(fn))
}

// receiver needs to be initialized in body (not used via tt.recv)
func receiverNeedsInit(fn *models.Function) bool {
	return fn.Receiver != nil && !isAliasReceiver(fn)
}

func (r *funcRenderer) render(out *bytes.Buffer) {
	fn := r.fn
	fmt.Fprintf(out, "func %s(t *testing.T) {\n", fn.TestName())
	if r.opts.Parallel {
		out.WriteString("\tt.Parallel()\n")
	}

	hasFields := isStructReceiverWithFields(fn)
	hasArgs := len(fn.Parameters) > 0

	if hasFields {
		out.WriteString("\ttype fields struct {\n")
		for _, f := range fn.Receiver.Fields {
			fmt.Fprintf(out, "\t\t%s %s\n", f.Name, f.Type.Value)
		}
		out.WriteString("\t}\n")
	}
	if hasArgs {
		out.WriteString("\ttype args struct {\n")
		for _, p := range fn.Parameters {
			fmt.Fprintf(out, "\t\t%s %s\n", p.Name, p.Type.String())
		}
		out.WriteString("\t}\n")
	}

	if r.opts.Named {
		out.WriteString("\ttests := map[string]struct {\n")
	} else {
		out.WriteString("\ttests := []struct {\n")
		out.WriteString("\t\tname\n")
	}
	if hasFields {
		out.WriteString("\t\tfields\n")
	}
	if receiverInTests(fn) {
		fmt.Fprintf(out, "\t\trecv %s\n", fn.Receiver.Type.Value)
	}
	if hasArgs {
		out.WriteString("\t\targs\n")
	}
	// wants - accumulate
	for _, res := range fn.Results {
		_, wn := resultVarName(res)
		fmt.Fprintf(out, "\t\t%s %s\n", strings.TrimPrefix(wn, "tt."), res.Type.Value)
	}
	if fn.ReturnsError {
		if r.opts.Template == "testify" {
			out.WriteString("\t\tassertion\n")
		} else {
			out.WriteString("\t\twantErr\n")
		}
	}
	// Actually I'll render into a structured form and do alignment later with go/format.
	// For now, write simple columns that go/format will align.
	out.WriteString("\t}{\n\t\t// TODO: Add test cases.\n\t}\n")

	// Loop
	if r.opts.Named {
		out.WriteString("\tfor name, tt := range tests {\n")
	} else {
		out.WriteString("\tfor _, tt := range tests {\n")
	}

	subtest := r.opts.Subtests
	indent := "\t\t"
	if subtest {
		if r.opts.Named {
			out.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			out.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if r.opts.Parallel {
			out.WriteString("\t\t\tt.Parallel()\n")
		}
		indent = "\t\t\t"
	}

	if receiverNeedsInit(fn) {
		pfx := ""
		if fn.Receiver.Type.IsStar {
			pfx = "&"
		}
		if isStructReceiverWithFields(fn) {
			fmt.Fprintf(out, "%s%s := %s%s{\n", indent, fn.Receiver.Name, pfx, fn.Receiver.ConcreteTypeName)
			for _, f := range fn.Receiver.Fields {
				fmt.Fprintf(out, "%s\t%s: tt.fields.%s,\n", indent, f.Name, f.Name)
			}
			fmt.Fprintf(out, "%s}\n", indent)
		} else {
			// empty struct or generic struct
			fmt.Fprintf(out, "%s%s := %s%s{}\n", indent, fn.Receiver.Name, pfx, fn.Receiver.ConcreteTypeName)
		}
	}

	r.renderCall(out, indent)

	if subtest {
		out.WriteString("\t\t})\n")
	}
	out.WriteString("\t}\n")
	out.WriteString("}\n")
}

func resultVarName(res *models.Field) (gotName, wantName string) {
	if res.IsNamed {
		return "got" + capitalize(res.Name), "tt.want" + capitalize(res.Name)
	}
	if res.Index == 0 {
		return "got", "tt.want"
	}
	return fmt.Sprintf("got%d", res.Index), fmt.Sprintf("tt.want%d", res.Index)
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	c := s[0]
	if c >= 'a' && c <= 'z' {
		c -= 'a' - 'A'
	}
	return string(c) + s[1:]
}

func (r *funcRenderer) renderCall(out *bytes.Buffer, indent string) {
	fn := r.fn
	var call strings.Builder
	if fn.Receiver != nil {
		if isAliasReceiver(fn) {
			call.WriteString("tt." + fn.Receiver.Name + "." + fn.Name)
		} else {
			call.WriteString(fn.Receiver.Name + "." + fn.Name)
		}
	} else {
		call.WriteString(fn.Name)
		if len(fn.TypeParams) > 0 {
			call.WriteString("[")
			for i, tp := range fn.TypeParams {
				if i > 0 {
					call.WriteString(", ")
				}
				call.WriteString(tp.Concrete)
			}
			call.WriteString("]")
		}
	}
	call.WriteString("(")
	for i, p := range fn.Parameters {
		if i > 0 {
			call.WriteString(", ")
		}
		call.WriteString("tt.args." + p.Name)
		if p.Type.IsVariadic {
			call.WriteString("...")
		}
	}
	call.WriteString(")")

	disp := fn.DisplayName()

	// Inputs string for -i flag
	inputsArgs := ""
	if r.opts.PrintInputs && len(fn.Parameters) > 0 {
		var pa []string
		for _, p := range fn.Parameters {
			pa = append(pa, "tt.args."+p.Name)
		}
		inputsArgs = strings.Join(pa, ", ")
	}

	nRes := len(fn.Results)

	if r.opts.Template == "testify" {
		if nRes == 0 && !fn.ReturnsError {
			fmt.Fprintf(out, "%s%s\n", indent, call.String())
			return
		}
		if nRes == 0 && fn.ReturnsError {
			fmt.Fprintf(out, "%stt.assertion(t, %s)\n", indent, call.String())
			return
		}
		var lhs []string
		for _, res := range fn.Results {
			gn, _ := resultVarName(res)
			lhs = append(lhs, gn)
		}
		if fn.ReturnsError {
			lhs = append(lhs, "err")
		}
		// If no error, simpler:
		if !fn.ReturnsError && nRes == 1 {
			// assert.Equal(t, tt.want, Call())
			res := fn.Results[0]
			_, wn := resultVarName(res)
			fmt.Fprintf(out, "%sassert.Equal(t, %s, %s)\n", indent, wn, call.String())
			return
		}
		fmt.Fprintf(out, "%s%s := %s\n", indent, strings.Join(lhs, ", "), call.String())
		if fn.ReturnsError {
			fmt.Fprintf(out, "%stt.assertion(t, err)\n", indent)
		}
		for _, res := range fn.Results {
			gn, wn := resultVarName(res)
			fmt.Fprintf(out, "%sassert.Equal(t, %s, %s)\n", indent, wn, gn)
		}
		return
	}

	// Default template
	// error check command: Fatalf (if more results to check) else Errorf
	// But for -nosubtests, it uses continue instead.
	errCmd := "t.Errorf"
	if nRes > 0 && fn.ReturnsError {
		if r.opts.Subtests {
			errCmd = "t.Fatalf"
		} else {
			errCmd = "t.Errorf"
		}
	}

	// Case 1: only error
	if nRes == 0 && fn.ReturnsError {
		fmt.Fprintf(out, "%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call.String())
		r.writeErrorfErr(out, indent+"\t", "t.Errorf", disp, inputsArgs, fn.Parameters)
		fmt.Fprintf(out, "%s}\n", indent)
		return
	}

	// Case 2: no results, no error - just call
	if nRes == 0 && !fn.ReturnsError {
		fmt.Fprintf(out, "%s%s\n", indent, call.String())
		return
	}

	// Case 3: single result, no error - inline
	if nRes == 1 && !fn.ReturnsError {
		res := fn.Results[0]
		gn, wn := resultVarName(res)
		cmp := comparisonExpr(res.Type.Value, gn, wn, r.opts.UseGoCmp)
		if isComplexType(res.Type.Value) {
			if r.opts.UseGoCmp {
				r.usedCmp = true
			} else {
				r.usedReflect = true
			}
		}
		fmt.Fprintf(out, "%sif %s := %s; %s {\n", indent, gn, call.String(), cmp)
		r.writeErrorfVal(out, indent+"\t", "t.Errorf", disp, gn, wn, res.Type.Value, inputsArgs, fn.Parameters, false)
		fmt.Fprintf(out, "%s}\n", indent)
		return
	}

	// Multi-result (maybe with error)
	var lhs []string
	for _, res := range fn.Results {
		gn, _ := resultVarName(res)
		lhs = append(lhs, gn)
	}
	if fn.ReturnsError {
		lhs = append(lhs, "err")
	}
	fmt.Fprintf(out, "%s%s := %s\n", indent, strings.Join(lhs, ", "), call.String())
	if fn.ReturnsError {
		fmt.Fprintf(out, "%sif (err != nil) != tt.wantErr {\n", indent)
		r.writeErrorfErr(out, indent+"\t", errCmd, disp, inputsArgs, fn.Parameters)
		if !r.opts.Subtests {
			fmt.Fprintf(out, "%s\tcontinue\n", indent)
		}
		fmt.Fprintf(out, "%s}\n", indent)
		if nRes > 0 {
			fmt.Fprintf(out, "%sif tt.wantErr {\n%s\treturn\n%s}\n", indent, indent, indent)
		}
	}
	useMultiLabel := nRes > 1
	for _, res := range fn.Results {
		gn, wn := resultVarName(res)
		cmp := comparisonExpr(res.Type.Value, gn, wn, r.opts.UseGoCmp)
		if isComplexType(res.Type.Value) {
			if r.opts.UseGoCmp {
				r.usedCmp = true
			} else {
				r.usedReflect = true
			}
		}
		fmt.Fprintf(out, "%sif %s {\n", indent, cmp)
		r.writeErrorfVal(out, indent+"\t", "t.Errorf", disp, gn, wn, res.Type.Value, inputsArgs, fn.Parameters, useMultiLabel)
		fmt.Fprintf(out, "%s}\n", indent)
	}
}

func (r *funcRenderer) writeErrorfErr(out *bytes.Buffer, indent, cmd, disp, inputsArgs string, params []*models.Field) {
	if r.opts.PrintInputs && len(params) > 0 {
		fa := strings.TrimPrefix(strings.Repeat(", %v", len(params)), ", ")
		fmt.Fprintf(out, "%s%s(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", indent, cmd, disp, fa, inputsArgs)
	} else {
		fmt.Fprintf(out, "%s%s(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", indent, cmd, disp)
	}
}

func (r *funcRenderer) writeErrorfVal(out *bytes.Buffer, indent, cmd, disp, gn, wn, typ, inputsArgs string, params []*models.Field, multiLabel bool) {
	useCmp := r.opts.UseGoCmp && isComplexType(typ)
	labelPart := ""
	if multiLabel {
		labelPart = gn + " "
	}
	if r.opts.PrintInputs && len(params) > 0 {
		fa := strings.TrimPrefix(strings.Repeat(", %v", len(params)), ", ")
		if useCmp {
			fmt.Fprintf(out, "%s%s(\"%s(%s) %s= %%v, want %%v\\ndiff=%%s\", %s, %s, %s, cmp.Diff(%s, %s))\n",
				indent, cmd, disp, fa, labelPart, inputsArgs, gn, wn, wn, gn)
		} else {
			fmt.Fprintf(out, "%s%s(\"%s(%s) %s= %%v, want %%v\", %s, %s, %s)\n",
				indent, cmd, disp, fa, labelPart, inputsArgs, gn, wn)
		}
	} else {
		if useCmp {
			fmt.Fprintf(out, "%s%s(\"%s() %s= %%v, want %%v\\ndiff=%%s\", %s, %s, cmp.Diff(%s, %s))\n",
				indent, cmd, disp, labelPart, gn, wn, wn, gn)
		} else {
			fmt.Fprintf(out, "%s%s(\"%s() %s= %%v, want %%v\", %s, %s)\n",
				indent, cmd, disp, labelPart, gn, wn)
		}
	}
}

func isComplexType(s string) bool {
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	if strings.HasPrefix(s, "*") || strings.HasPrefix(s, "[") || strings.HasPrefix(s, "map") ||
		strings.HasPrefix(s, "chan") || strings.HasPrefix(s, "<-chan") || strings.HasPrefix(s, "chan<-") ||
		strings.HasPrefix(s, "func(") || strings.HasPrefix(s, "func ") ||
		strings.HasPrefix(s, "interface") || strings.HasPrefix(s, "struct{") || strings.HasPrefix(s, "struct ") {
		return true
	}
	// type param identifier (single uppercase)
	if len(s) == 1 && s[0] >= 'A' && s[0] <= 'Z' {
		return true
	}
	return false
}

func comparisonExpr(typ, gn, wn string, useGoCmp bool) string {
	if isComplexType(typ) {
		if useGoCmp {
			return fmt.Sprintf("!cmp.Equal(%s, %s)", wn, gn)
		}
		return fmt.Sprintf("!reflect.DeepEqual(%s, %s)", gn, wn)
	}
	return fmt.Sprintf("%s != %s", gn, wn)
}
