package input

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Expand expands a single arg (file, dir, or ./... pattern) into list of .go files.
// Returns (files, dirName-or-filePath, error).
// For directory arg, all .go files (excluding _test.go) in that dir.
// For ./... patterns, walks subdirectories.
func Expand(arg string) ([][]string, []string, error) {
	// Check for ./... pattern
	if strings.HasSuffix(arg, "/...") {
		base := strings.TrimSuffix(arg, "/...")
		if base == "" || base == "." {
			base = "."
		}
		var groups [][]string
		var names []string
		err := filepath.Walk(base, func(p string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if info.IsDir() {
				files, _ := collectGoFiles(p)
				if len(files) > 0 {
					groups = append(groups, files)
					names = append(names, p)
				}
			}
			return nil
		})
		if err != nil {
			return nil, nil, fmt.Errorf("filepath.Walk: %v", err)
		}
		return groups, names, nil
	}

	fi, err := os.Stat(arg)
	if err != nil {
		return nil, nil, fmt.Errorf("os.Stat: %v", err)
	}
	if fi.IsDir() {
		files, err := collectGoFiles(arg)
		if err != nil {
			return nil, nil, err
		}
		if len(files) == 0 {
			return nil, []string{arg}, nil
		}
		return [][]string{files}, []string{arg}, nil
	}
	// Regular file - must be .go
	if !strings.HasSuffix(arg, ".go") {
		return nil, nil, fmt.Errorf("no Go source files found at %s", arg)
	}
	return [][]string{{arg}}, []string{arg}, nil
}

// collectGoFiles returns all .go files (not _test.go) in dir.
func collectGoFiles(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("ioutil.ReadDir: %v", err)
	}
	var files []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasSuffix(name, ".go") {
			continue
		}
		if strings.HasSuffix(name, "_test.go") {
			continue
		}
		files = append(files, filepath.Join(dir, name))
	}
	return files, nil
}

// TestFilePath returns the test file path for the given source file.
func TestFilePath(src string) string {
	dir := filepath.Dir(src)
	base := filepath.Base(src)
	name := strings.TrimSuffix(base, ".go") + "_test.go"
	return filepath.Join(dir, name)
}

// SiblingFiles returns all .go files in the directory of src (excluding _test.go).
func SiblingFiles(src string) ([]string, error) {
	return collectGoFiles(filepath.Dir(src))
}
EOF
echo done

