cat > /workspace/internal/process/process.go <<'EOF'
package process

import (
	"bytes"
	"fmt"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"regexp"
	"strings"

	"gotests/internal/goparser"
	"gotests/internal/input"
	"gotests/internal/models"
	"gotests/internal/render"
)

// Options contains all processing options.
type Options struct {
	All         bool
	Exported    bool
	Only        string
	Excl        string
	PrintInputs bool
	Subtests    bool
	Named       bool
	Parallel    bool
	Write       bool
	UseGoCmp    bool
	Template    string
	TemplateDir string
}

// Run processes the given source paths and writes tests.
func Run(args []string, opts Options) error {
	// Validate filter selection
	if !opts.All && !opts.Exported && opts.Only == "" && opts.Excl == "" {
		fmt.Println("Please specify either the -only, -excl, -exported, or -all flag")
		return nil
	}

	var onlyRe, exclRe *regexp.Regexp
	var err error
	if opts.Only != "" {
		onlyRe, err = regexp.Compile(opts.Only)
		if err != nil {
			return fmt.Errorf("invalid regexp for -only: %v", err)
		}
	}
	if opts.Excl != "" {
		exclRe, err = regexp.Compile(opts.Excl)
		if err != nil {
			return fmt.Errorf("invalid regexp for -excl: %v", err)
		}
	}

	for _, arg := range args {
		groups, names, err := input.Expand(arg)
		if err != nil {
			return fmt.Errorf("input.Files: %v", err)
		}
		if len(groups) == 0 {
			fmt.Printf("No tests generated for %s\n", arg)
			continue
		}
		anyGenerated := false
		for gi, group := range groups {
			name := arg
			if gi < len(names) {
				name = names[gi]
			}
			generated := 0
			for _, file := range group {
				n, err := processFile(file, group, opts, onlyRe, exclRe)
				if err != nil {
					return err
				}
				generated += n
			}
			if generated > 0 {
				anyGenerated = true
			}
			_ = name
		}
		if !anyGenerated {
			fmt.Printf("No tests generated for %s\n", arg)
		}
	}
	return nil
}

// processFile parses a single source file, filters functions, renders tests.
// Returns number of tests generated.
func processFile(src string, siblings []string, opts Options, onlyRe, exclRe *regexp.Regexp) (int, error) {
	p := &goparser.Parser{}
	res, err := p.Parse(src, siblings)
	if err != nil {
		return 0, fmt.Errorf("Parser.Parse source file: %v", err)
	}

	// Filter
	var funcs []*models.Function
	for _, fn := range res.Functions {
		if !selected(fn, opts, onlyRe, exclRe) {
			continue
		}
		funcs = append(funcs, fn)
	}
	if len(funcs) == 0 {
		return 0, nil
	}

	// Read existing test file
	testPath := input.TestFilePath(src)
	var existingFuncs map[string]bool
	var existingImports []render.Import
	var existingTestContent []byte
	if data, err := os.ReadFile(testPath); err == nil {
		existingTestContent = data
		existingFuncs, existingImports = parseExistingTestFile(testPath)
	}

	// Filter out funcs that already have tests
	var pending []*models.Function
	for _, fn := range funcs {
		tn := fn.TestName()
		if existingFuncs[tn] {
			continue
		}
		pending = append(pending, fn)
	}
	if len(pending) == 0 {
		return 0, nil
	}

	// Merge imports from source file + existing test file
	var imports []render.Import
	for _, im := range res.Header.Imports {
		imports = append(imports, render.Import{Name: im.Name, Path: im.Path})
	}
	for _, im := range existingImports {
		// avoid duplicate imports
		dup := false
		for _, existing := range imports {
			if existing.Path == im.Path && existing.Name == im.Name {
				dup = true
				break
			}
		}
		if !dup {
			imports = append(imports, im)
		}
	}

	rOpts := render.Options{
		PrintInputs: opts.PrintInputs,
		Subtests:    opts.Subtests,
		Named:       opts.Named,
		Parallel:    opts.Parallel,
		UseGoCmp:    opts.UseGoCmp,
		Template:    opts.Template,
	}

	generated := render.Render(res.Header.Package, imports, pending, rOpts)

	// Format
	formatted, ferr := format.Source(generated)
	if ferr != nil {
		// Fall back to unformatted; print error for debugging.
		fmt.Fprintf(os.Stderr, "gotests: format error: %v\n", ferr)
		formatted = generated
	}

	// If existing test file exists, merge: keep existing file + append new funcs.
	var finalOut []byte
	if len(existingTestContent) > 0 {
		finalOut = mergeTestFile(existingTestContent, imports, res.Header.Package, pending, rOpts)
	} else {
		finalOut = formatted
	}

	for _, fn := range pending {
		fmt.Fprintf(os.Stderr, "Generated %s\n", fn.TestName())
	}

	if opts.Write {
		if err := os.WriteFile(testPath, finalOut, 0644); err != nil {
			return 0, err
		}
	} else {
		os.Stdout.Write(finalOut)
	}

	return len(pending), nil
}

func selected(fn *models.Function, opts Options, onlyRe, exclRe *regexp.Regexp) bool {
	if exclRe != nil && exclRe.MatchString(fn.Name) {
		return false
	}
	if opts.Exported && !fn.IsExported {
		return false
	}
	if onlyRe != nil {
		return onlyRe.MatchString(fn.Name)
	}
	return opts.All || opts.Exported || opts.Excl != ""
}

