	// Render new test funcs (full file). Extract body and new imports.
	generated := render.Render(pkg, imports, pending, rOpts)
	// Parse generated to separate imports from body.
	fset := token.NewFileSet()
	gf, err := parser.ParseFile(fset, "", generated, parser.ParseComments)
	if err != nil {
		return existing
	}
	// Extract imports (full list used in the new file).
	var newImports []render.Import
	for _, imp := range gf.Imports {
		name := ""
		if imp.Name != nil {
			name = imp.Name.Name
		}
		p := strings.Trim(imp.Path.Value, "\"")
		newImports = append(newImports, render.Import{Name: name, Path: p})
	}
	// Extract body (everything after imports).
	var bodyStart int
	if len(gf.Decls) > 0 {
		// Skip GenDecls for imports
		for _, d := range gf.Decls {
			gd, ok := d.(*ast.GenDecl)
			if ok && gd.Tok == token.IMPORT {
				continue
			}
			bodyStart = fset.Position(d.Pos()).Offset
			break
		}
	}
	body := generated[bodyStart:]

	// Parse existing file
	ef, err := parser.ParseFile(fset, "", existing, parser.ParseComments)
	if err != nil {
		return existing
	}

	// Collect existing imports
	existingImportsMap := map[string]string{} // path -> name
	for _, imp := range ef.Imports {
		p := strings.Trim(imp.Path.Value, "\"")
		name := ""
		if imp.Name != nil {
			name = imp.Name.Name
		}
		existingImportsMap[p] = name
	}

	var toAdd []render.Import
	for _, im := range newImports {
		if _, ok := existingImportsMap[im.Path]; !ok {
			toAdd = append(toAdd, im)
		}
	}

	// Rewrite the import block in existing
	merged := rewriteImports(existing, ef, fset, toAdd)

	// Append body
	if !bytes.HasSuffix(merged, []byte("\n")) {
		merged = append(merged, '\n')
	}
	merged = append(merged, '\n')
	merged = append(merged, body...)

	if formatted, ferr := format.Source(merged); ferr == nil {
		return formatted
	}
	return merged
}

// rewriteImports returns src with imports replaced by merging in new imports.
// It finds the GenDecl IMPORT block (if any) and replaces it with a combined block.
// If no import block exists, one is inserted after the package clause.
func rewriteImports(src []byte, f *ast.File, fset *token.FileSet, newImports []render.Import) []byte {
	if len(newImports) == 0 {
		return src
	}
	// Find first import decl block
	var first *ast.GenDecl
	var last *ast.GenDecl
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		if first == nil {
			first = gd
		}
		last = gd
	}

	// Build new import block text
	var buf bytes.Buffer
	buf.WriteString("import (\n")
	// Existing imports
	for _, imp := range f.Imports {
		name := ""
		if imp.Name != nil {
			name = imp.Name.Name
		}
		path := strings.Trim(imp.Path.Value, "\"")
		if name == "" {
			fmt.Fprintf(&buf, "\t%q\n", path)
		} else {
			fmt.Fprintf(&buf, "\t%s %q\n", name, path)
		}
	}
	// Separator if any external new imports
	needSep := false
	isStd := func(p string) bool {
		i := strings.Index(p, "/")
		first := p
		if i >= 0 {
			first = p[:i]
		}
		return !strings.Contains(first, ".")
	}
	hasExternal := false
	for _, im := range newImports {
		if !isStd(im.Path) {
			hasExternal = true
		}
	}
	_ = needSep
	_ = hasExternal
	for _, im := range newImports {
		if im.Name == "" {
			fmt.Fprintf(&buf, "\t%q\n", im.Path)
		} else {
			fmt.Fprintf(&buf, "\t%s %q\n", im.Name, im.Path)
		}
	}
	buf.WriteString(")")

	if first != nil {
		start := fset.Position(first.Pos()).Offset
		end := fset.Position(last.End()).Offset
		var out bytes.Buffer
		out.Write(src[:start])
		out.Write(buf.Bytes())
		out.Write(src[end:])
		return out.Bytes()
	}
	// No import declarations - insert after package line
	pkgEnd := fset.Position(f.Name.End()).Offset
	// find end of line
	nl := bytes.IndexByte(src[pkgEnd:], '\n')
	insertAt := pkgEnd + nl + 1
	var out bytes.Buffer
	out.Write(src[:insertAt])
	out.WriteString("\n")
	out.Write(buf.Bytes())
	out.WriteString("\n")
	out.Write(src[insertAt:])
	return out.Bytes()
}
